/// The `zwp_tablet_pad_group_v2` interface's events.
#[derive(Debug)]
pub enum ZwpTabletPadGroupV2Event {
    /// Buttons announced. Sent on wp_tablet_pad_group initialization to announce the available buttons in the group.
    /// Button indices start at 0, a button may only be in one group at a time.
    Buttons {
        /// Buttons in this group.
        buttons: Vec<u8>,
    },
    /// Ring announced. Sent on wp_tablet_pad_group initialization to announce available rings. One event is sent for
    /// each ring available on this pad group.
    Ring { ring: ZwpTabletPadRingV2 },
    /// Strip announced. Sent on wp_tablet_pad initialization to announce available strips. One event is sent for each
    /// strip available on this pad group.
    Strip { strip: ZwpTabletPadStripV2 },
    /// Mode-switch ability announced. Sent on wp_tablet_pad_group initialization to announce that the pad group may
    /// switch between modes. A client may use a mode to store a specific configuration for buttons, rings and strips
    /// and use the wl_tablet_pad_group.mode_switch event to toggle between these configurations.
    Modes {
        /// The number of modes.
        modes: u32,
    },
    /// Tablet group description events sequence complete. This event is sent immediately to signal the end of the
    /// initial burst of descriptive events. A client may consider the static description of the tablet to be complete
    /// and finalize initialization of the tablet group.
    Done,
    /// Mode switch event. Notification that the mode was switched.
    ModeSwitch {
        /// The time of the event with millisecond granularity.
        time: u32,
        serial: u32,
        /// The new mode of the pad.
        mode: u32,
    },
}

impl ZwpTabletPadGroupV2Event {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Buttons { buttons: args.array()? },
            1 => Self::Ring { ring: args.new_id()? },
            2 => Self::Strip { strip: args.new_id()? },
            3 => Self::Modes { modes: args.uint()? },
            4 => Self::Done,
            5 => Self::ModeSwitch { time: args.uint()?, serial: args.uint()?, mode: args.uint()? },
            _ => return None,
        })
    }
}

