/// The `zwp_tablet_pad_v2` interface's events.
#[derive(Debug)]
pub enum ZwpTabletPadV2Event {
    /// Group announced. Sent on wp_tablet_pad initialization to announce available groups. One event is sent for each
    /// pad group available.
    Group { pad_group: ZwpTabletPadGroupV2 },
    /// Path to the device. A system-specific device path that indicates which device is behind this wp_tablet_pad. This
    /// information may be used to gather additional information about the device, e.g. through libwacom.
    Path {
        /// Path to local device.
        path: String,
    },
    /// Buttons announced. Sent on wp_tablet_pad initialization to announce the available buttons.
    Buttons {
        /// The number of buttons.
        buttons: u32,
    },
    /// Pad description event sequence complete. This event signals the end of the initial burst of descriptive events.
    /// A client may consider the static description of the pad to be complete and finalize initialization of the pad.
    Done,
    /// Physical button state. Sent whenever the physical state of a button changes.
    Button {
        /// The time of the event with millisecond granularity.
        time: u32,
        /// The index of the button that changed state.
        button: u32,
        state: ZwpTabletPadV2ButtonState,
    },
    /// Enter event. Notification that this pad is focused on the specified surface.
    Enter {
        /// Serial number of the enter event.
        serial: u32,
        /// The tablet the pad is attached to.
        tablet: ObjectId,
        /// Surface the pad is focused on.
        surface: ObjectId,
    },
    /// Leave event. Notification that this pad is no longer focused on the specified surface.
    Leave {
        /// Serial number of the leave event.
        serial: u32,
        /// Surface the pad is no longer focused on.
        surface: ObjectId,
    },
    /// Pad removed event. Sent when the pad has been removed from the system. When a tablet is removed its pad(s) will
    /// be removed too.
    Removed,
}

impl ZwpTabletPadV2Event {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Group { pad_group: args.new_id()? },
            1 => Self::Path { path: args.string()? },
            2 => Self::Buttons { buttons: args.uint()? },
            3 => Self::Done,
            4 => Self::Button {
                time: args.uint()?,
                button: args.uint()?,
                state: ZwpTabletPadV2ButtonState(args.uint()?),
            },
            5 => Self::Enter { serial: args.uint()?, tablet: args.object()?, surface: args.object()? },
            6 => Self::Leave { serial: args.uint()?, surface: args.object()? },
            7 => Self::Removed,
            _ => return None,
        })
    }
}

